// Folio's long-form text: an article body set in Newsreader with ruled block quotes, press-red links,
// figures with italic captions, tables, a double rule for <hr>, and an optional drop cap. Wrap rendered
// Markdown or MDX in it. Everything is in the classes, so no extra CSS file is needed.
//
// Anything marked "not-prose" keeps its own look: the editorial components (PullQuote, Footnotes,
// NewsletterSignup…) already are, and you can add the class to a Card or a Table you drop in.
import * as React from "react"
import { cn } from "@/lib/utils"

// Every rule below skips .not-prose and whatever is inside it.
const proseClass = cn(
  "max-w-[68ch] font-serif text-ink [font-optical-sizing:auto]",
  "data-[size=sm]:text-[17px] data-[size=sm]:leading-[1.6] data-[size=default]:text-[19px] data-[size=default]:leading-[1.62] data-[size=lg]:text-[21px] data-[size=lg]:leading-[1.6]",
  // Space between blocks, at zero specificity so a child's own margin (a PullQuote's, or yours) wins.
  "[:where(&>*+*)]:mt-[1em] [&>:first-child:not(.not-prose)]:mt-0",
  // Headings
  "[&_h2:not(.not-prose,.not-prose_*)]:mt-[1.8em] [&_h2:not(.not-prose,.not-prose_*)]:text-[1.55em] [&_h2:not(.not-prose,.not-prose_*)]:leading-[1.15] [&_h2:not(.not-prose,.not-prose_*)]:font-bold [&_h2:not(.not-prose,.not-prose_*)]:tracking-[-0.02em]",
  "[&_h3:not(.not-prose,.not-prose_*)]:mt-[1.6em] [&_h3:not(.not-prose,.not-prose_*)]:text-[1.2em] [&_h3:not(.not-prose,.not-prose_*)]:leading-[1.25] [&_h3:not(.not-prose,.not-prose_*)]:font-semibold",
  "[&_h4:not(.not-prose,.not-prose_*)]:mt-[1.4em] [&_h4:not(.not-prose,.not-prose_*)]:font-sans [&_h4:not(.not-prose,.not-prose_*)]:text-[0.8em] [&_h4:not(.not-prose,.not-prose_*)]:font-semibold",
  // Text
  "[&_a:not(.not-prose,.not-prose_*)]:text-press [&_a:not(.not-prose,.not-prose_*)]:underline [&_a:not(.not-prose,.not-prose_*)]:decoration-1 [&_a:not(.not-prose,.not-prose_*)]:underline-offset-[3px] [&_a:not(.not-prose,.not-prose_*):hover]:text-ink",
  "[&_strong:not(.not-prose,.not-prose_*)]:font-semibold [&_em:not(.not-prose,.not-prose_*)]:italic",
  "[&_ul:not(.not-prose,.not-prose_*)]:list-disc [&_ul:not(.not-prose,.not-prose_*)]:pl-[1.25em] [&_ol:not(.not-prose,.not-prose_*)]:list-decimal [&_ol:not(.not-prose,.not-prose_*)]:pl-[1.4em] [&_li:not(.not-prose,.not-prose_*)]:mt-[0.35em] [&_li:not(.not-prose,.not-prose_*)]:pl-[0.15em] [&_li:not(.not-prose,.not-prose_*)::marker]:text-ink-2",
  "[&_blockquote:not(.not-prose,.not-prose_*)]:border-l-[3px] [&_blockquote:not(.not-prose,.not-prose_*)]:border-press [&_blockquote:not(.not-prose,.not-prose_*)]:pl-[1em] [&_blockquote:not(.not-prose,.not-prose_*)]:text-ink-2 [&_blockquote:not(.not-prose,.not-prose_*)]:italic",
  // Code is content here, so it may be monospace.
  "[&_:not(pre)>code:not(.not-prose,.not-prose_*)]:rounded-(--radius) [&_:not(pre)>code:not(.not-prose,.not-prose_*)]:bg-newsprint [&_:not(pre)>code:not(.not-prose,.not-prose_*)]:px-[0.3em] [&_:not(pre)>code:not(.not-prose,.not-prose_*)]:py-[0.1em] [&_:not(pre)>code:not(.not-prose,.not-prose_*)]:font-mono [&_:not(pre)>code:not(.not-prose,.not-prose_*)]:text-[0.8em]",
  "[&_pre:not(.not-prose,.not-prose_*)]:overflow-x-auto [&_pre:not(.not-prose,.not-prose_*)]:rounded-(--radius) [&_pre:not(.not-prose,.not-prose_*)]:border [&_pre:not(.not-prose,.not-prose_*)]:border-hairline [&_pre:not(.not-prose,.not-prose_*)]:bg-newsprint [&_pre:not(.not-prose,.not-prose_*)]:p-[1em] [&_pre:not(.not-prose,.not-prose_*)]:font-mono [&_pre:not(.not-prose,.not-prose_*)]:text-[0.75em] [&_pre:not(.not-prose,.not-prose_*)]:leading-[1.6]",
  // Rules, figures, tables
  "[&_hr:not(.not-prose,.not-prose_*)]:my-[2em] [&_hr:not(.not-prose,.not-prose_*)]:h-[8px] [&_hr:not(.not-prose,.not-prose_*)]:border-x-0 [&_hr:not(.not-prose,.not-prose_*)]:border-y-2 [&_hr:not(.not-prose,.not-prose_*)]:border-rule",
  "[&_figure:not(.not-prose,.not-prose_*)]:my-[1.6em] [&_img:not(.not-prose,.not-prose_*)]:w-full [&_img:not(.not-prose,.not-prose_*)]:rounded-(--radius)",
  "[&_figcaption:not(.not-prose,.not-prose_*)]:mt-[0.6em] [&_figcaption:not(.not-prose,.not-prose_*)]:text-[0.84em] [&_figcaption:not(.not-prose,.not-prose_*)]:leading-[1.45] [&_figcaption:not(.not-prose,.not-prose_*)]:text-ink-2 [&_figcaption:not(.not-prose,.not-prose_*)]:italic",
  "[&_table:not(.not-prose,.not-prose_*)]:w-full [&_table:not(.not-prose,.not-prose_*)]:border-collapse [&_table:not(.not-prose,.not-prose_*)]:font-sans [&_table:not(.not-prose,.not-prose_*)]:text-[0.78em]",
  "[&_th:not(.not-prose,.not-prose_*)]:border-b-2 [&_th:not(.not-prose,.not-prose_*)]:border-rule [&_th:not(.not-prose,.not-prose_*)]:py-[0.5em] [&_th:not(.not-prose,.not-prose_*)]:pr-[1em] [&_th:not(.not-prose,.not-prose_*)]:text-left [&_th:not(.not-prose,.not-prose_*)]:font-semibold",
  "[&_td:not(.not-prose,.not-prose_*)]:border-b [&_td:not(.not-prose,.not-prose_*)]:border-hairline [&_td:not(.not-prose,.not-prose_*)]:py-[0.5em] [&_td:not(.not-prose,.not-prose_*)]:pr-[1em]",
)

const dropCapClass =
  "[&>p:first-of-type]:first-letter:float-left [&>p:first-of-type]:first-letter:mt-[0.08em] [&>p:first-of-type]:first-letter:mr-[0.08em] [&>p:first-of-type]:first-letter:text-[3.7em] [&>p:first-of-type]:first-letter:leading-[0.8] [&>p:first-of-type]:first-letter:font-bold [&>p:first-of-type]:first-letter:text-press"

function Prose({
  className,
  size = "default",
  dropCap = false,
  ...props
}: React.ComponentProps<"div"> & {
  size?: "sm" | "default" | "lg"
  /** A press-red drop cap on the first paragraph. */
  dropCap?: boolean
}) {
  return <div data-slot="prose" data-size={size} className={cn(proseClass, dropCap && dropCapClass, className)} {...props} />
}

export { Prose }
